function WorkflowDiagram({ lessonId, lang, uid }: RenderProps) {
  const l = (uk: string, en: string) => choose(lang, uk, en);
  const stages = lessonId === 'cnc-prove-out' ? [
    {kind:'check', label:l('Симуляція', 'Simulation')}, {kind:'machine',label:l('Контрольований\nпрогін', 'Controlled\nprove-out')}, {kind:'inspect',label:l('Контроль першої\nдеталі', 'First-part\ninspection')},
  ] : lessonId === 'machine-assessment' ? [
    {kind:'post',label:l('Документи\nй ідентифікація', 'Documents\n& identity')}, {kind:'check',label:l('Історія\nта статус', 'History\n& status')}, {kind:'machine',label:l('Огляд і межі\nсервісу', 'Inspection &\nservice scope')}, {kind:'check',label:l('Приймання\nдо роботи', 'Acceptance\nfor use')},
  ] : lessonId === 'tooling-requirements' ? [
    {kind:'model',label:l('Матеріал\nі вимоги', 'Material\n& requirements')}, {kind:'path',label:l('Операція\nй доступ', 'Operation\n& access')}, {kind:'machine',label:l('Можливості\nверстата', 'Machine\ncapability')}, {kind:'holder',label:l('Державка\nта інструмент', 'Holder\n& cutter')},
  ] : lessonId === 'reverse-validation' ? [
    {kind:'model',label:l('Зразок і вимоги', 'Sample & criteria')}, {kind:'post',label:l('Креслення\nта ревізія', 'Drawing\n& revision')}, {kind:'machine',label:l('Виготовлення', 'Manufacture')}, {kind:'inspect',label:l('Контроль\nі примірка', 'Inspect\n& trial-fit')},
  ] : [
    {kind:'model',label:'CAD'}, {kind:'path',label:'CAM'}, {kind:'check',label:l('Симуляція', 'Simulation')}, {kind:'post',label:l('Постпроцесор', 'Postprocessor')}, {kind:'machine',label:l('Верстат', 'Machine')},
  ];
  const gap = stages.length === 3 ? 247 : stages.length === 4 ? 189 : 151;
  const width = stages.length === 3 ? 210 : stages.length === 4 ? 158 : 128;
  const note = lessonId === 'reverse-validation' ? l('Нерухома примірка ≠ підтверджена міцність під навантаженням.', 'A stationary trial fit ≠ verified strength under load.') : lessonId === 'machine-assessment' ? l('Невідомий стан — підстава для перевірки, а не для пробного різання.', 'Unknown condition calls for assessment, not a trial cut.') : lessonId === 'tooling-requirements' ? l('Перевірте сумісність усього ланцюга, а не лише діаметр інструмента.', 'Verify compatibility of the whole system, not just cutter diameter.') : l('Симуляція не замінює перевірки реального встановлення.', 'Simulation does not replace verification of the actual setup.');
  return <>{stages.map((stage, i)=>{const x=37 + i*gap;return <g key={`${stage.kind}-${i}`}><Panel x={x} y={75} width={width} height={234}><ProcessSketch kind={stage.kind} x={x+width/2} y={147} uid={uid}/><Label x={x+width/2} y={249} anchor="middle">{stage.label}</Label></Panel>{i<stages.length-1&&<Arrow x1={x+width+6} y1={179} x2={x+gap-7} y2={179} uid={uid}/>}</g>})}<Label x={400} y={365} anchor="middle" color={AMBER}>{note}</Label></>;
}

