export default function LessonDiagram({ lessonId, lang, step }: DiagramProps) {
  const uid = `lesson-figure-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const info = figures[lessonId];
  if (!info || (step !== undefined && !supportingSteps[lessonId]?.includes(step))) return null;
  const title = (step === undefined ? info.title : detailTitles[`${lessonId}:${step}`] || info.title)[lang === 'uk' ? 0 : 1];
  const caption = info.caption[lang === 'uk' ? 0 : 1];
  const Renderer = renderers[info.renderer];
  return <figure className={`lesson-diagram${step === undefined ? '' : ' lesson-diagram-detail'}`} data-lesson-diagram={lessonId}>
    <div className="lesson-diagram-heading"><span className="lesson-diagram-index" aria-hidden="true">{choose(lang, 'СХЕМА', 'FIGURE')}</span><h3>{title}</h3></div>
    <div className="lesson-diagram-viewport" tabIndex={0} role="region" aria-label={title}><svg className="lesson-diagram-svg" viewBox="0 0 800 420" role="img" aria-labelledby={`${uid}-title ${uid}-desc`} xmlns="http://www.w3.org/2000/svg"><title id={`${uid}-title`}>{title}</title><desc id={`${uid}-desc`}>{caption}</desc><defs>{[['blue',BLUE],['gray',GRAY],['amber',AMBER],['green',GREEN]].map(([name,color])=><marker key={name} id={`${uid}-${name}`} viewBox="0 0 10 10" refX={8} refY={5} markerWidth={9} markerHeight={9} orient="auto-start-reverse" markerUnits="userSpaceOnUse"><path d="M0 0 10 5 0 10Z" fill={color}/></marker>)}<pattern id={`${uid}-hatch`} width={9} height={9} patternUnits="userSpaceOnUse"><rect width={9} height={9} fill="#e8eef7"/><path d="m-2 2 4-4m-2 11 9-9m-2 11 4-4" stroke="#94a3b8" strokeWidth={1}/></pattern></defs><Renderer lessonId={lessonId} lang={lang} uid={uid} detail={step}/></svg></div>
    <span className="lesson-diagram-scroll-note">{choose(lang, 'Проведіть убік, щоб переглянути всю схему', 'Swipe sideways to see the whole diagram')}</span>
    <figcaption><p>{caption}</p><span>{choose(lang, 'Навчальна схема · не в масштабі', 'Educational schematic · not to scale')}</span></figcaption>
  </figure>;
}
